//! Admission tests for scoped numeric bit addresses. Expected
//! bits/headers are literals or elementary masks, not generated by the wrapper.
use crate::bit_tools::BitAction;
use crate::indexed_bit_number::{IndexedBitNumberAction, IndexedBitNumberPredicate};
use crate::numeric_contacts::NumericPredicate;
use crate::plc::{Area, Device, Memory, Program, ScanStatus, Simulator, compile_il};
use std::collections::BTreeSet;

fn d(raw: &str) -> Device {
    raw.parse().unwrap()
}
fn args(raw: &str) -> Vec<String> {
    raw.split_whitespace().map(str::to_owned).collect()
}
fn action(raw: &str) -> IndexedBitNumberAction {
    let words = args(raw);
    IndexedBitNumberAction::parse(&words[0], &words[1..]).unwrap()
}
fn pred(raw: &str) -> IndexedBitNumberPredicate {
    let words = args(raw);
    IndexedBitNumberPredicate::parse(&words[0], &words[1..]).unwrap()
}
fn run(sim: &mut Simulator, p: &Program) {
    sim.scan(p, 0);
    assert_eq!(sim.last_scan, ScanStatus::Complete);
}
fn seed(m: &mut Memory) {
    for (n, on) in [(1020, true), (1021, false), (1022, true)] {
        m.set_system(n, on);
    }
}
fn flags(m: &Memory) -> [bool; 3] {
    [1020, 1021, 1022].map(|n| m.system_bit(n))
}
fn packed(m: &Memory, base: Device, width: u16) -> u32 {
    (0..width).fold(0, |v, bit| {
        v | (u32::from(m.bit(Device {
            index: base.index + bit,
            ..base
        })) << bit)
    })
}
fn put_group(m: &mut Memory, base: Device, width: u16, value: u32) {
    for bit in 0..width {
        let address = Device {
            index: base.index + bit,
            ..base
        };
        let on = value & (1u32 << bit) != 0;
        if base.area == Area::X {
            m.set_input(address, on);
        } else {
            m.set_internal(address, on);
        }
    }
}
const ACTIONS: [(&str, u16, bool); 6] = [
    ("BOUT", 0x3402, false),
    ("DBOUT", 0x3502, true),
    ("BSET", 0x3602, false),
    ("DBSET", 0x3702, true),
    ("BRST", 0x3802, false),
    ("DBRST", 0x3902, true),
];
const CONTACTS: [(&str, &str, u16, bool, bool); 12] = [
    ("BLD", "LD", 0x3a02, false, false),
    ("DBLD", "LD", 0x3b02, true, false),
    ("BLDI", "LD", 0x3c02, false, true),
    ("DBLDI", "LD", 0x3d02, true, true),
    ("BAND", "AND", 0x3e02, false, false),
    ("DBAND", "AND", 0x3f02, true, false),
    ("BANI", "AND", 0x4002, false, true),
    ("DBANI", "AND", 0x4102, true, true),
    ("BOR", "OR", 0x4202, false, false),
    ("DBOR", "OR", 0x4302, true, false),
    ("BORI", "OR", 0x4402, false, true),
    ("DBORI", "OR", 0x4502, true, true),
];

#[test]
fn all_eighteen_literal_headers_and_fields_keep_five_or_nine_word_visits() {
    for (name, header, wide) in ACTIONS {
        let text = format!("{name} D20F7 D10E1");
        let a = action(&text);
        let expected = if wide {
            vec![
                header, 0x28f6, 0x8089, 0x0080, 0x0080, 0x14e6, 0x8086, 0x0080, 0x0080,
            ]
        } else {
            vec![header, 0x28f6, 0x8089, 0x14e6, 0x8086]
        };
        assert_eq!(a.native_words().unwrap(), expected);
        assert_eq!(a.label(), text);
        assert_eq!(a.source_count(), 2);
        let p = compile_il(&format!("LD X0\n{text}\nMOV K9 D300\nEND")).unwrap();
        assert!(p.requires_vm());
        let encoded = crate::es2_encoder::encode(&p).unwrap();
        let pc = usize::from(encoded.action_pc[0]);
        assert_eq!(&encoded.words[pc..pc + expected.len()], expected);
        assert_eq!(usize::from(encoded.action_pc[1]), pc + expected.len());
        let mut sim = Simulator::default();
        sim.memory.set_input(d("X0"), true);
        sim.memory.set_word(d("D1182"), 1);
        sim.memory.set_word(d("D1195"), 2);
        sim.memory.set_double_word(d("D11"), 3);
        sim.memory.set_double_word(d("D22"), 0x18);
        seed(&mut sim.memory);
        run(&mut sim, &p);
        assert_eq!(
            sim.memory.double_word(d("D22")),
            if name.contains("RST") { 0x10 } else { 0x18 }
        );
        assert_eq!(sim.memory.word(d("D300")), 9);
        assert_eq!(flags(&sim.memory), [true, false, true]);
    }
    for (name, prefix, header, wide, inverted) in CONTACTS {
        let text = format!("{name} D20F7 D10E1");
        let a = pred(&text);
        let expected = if wide {
            vec![
                header, 0x28f6, 0x8089, 0x0080, 0x0080, 0x14e6, 0x8086, 0x0080, 0x0080,
            ]
        } else {
            vec![header, 0x28f6, 0x8089, 0x14e6, 0x8086]
        };
        assert_eq!(a.native_words(prefix).unwrap(), expected);
        assert_eq!(a.label(prefix), text);
        let leading = match prefix {
            "AND" => "LD X0\n",
            "OR" => "LD X1\n",
            _ => "",
        };
        let p = compile_il(&format!(
            "{leading}{text}\nOUT Y0\nLDI X7\nMOV K9 D300\nEND"
        ))
        .unwrap();
        let encoded = crate::es2_encoder::encode(&p).unwrap();
        let pc = usize::from(prefix != "LD");
        assert_eq!(&encoded.words[pc..pc + expected.len()], expected);
        assert_eq!(usize::from(encoded.action_pc[0]), pc + expected.len());
        let mut sim = Simulator::default();
        sim.memory.set_input(d("X0"), true);
        sim.memory.set_word(d("D1182"), 1);
        sim.memory.set_word(d("D1195"), 2);
        sim.memory.set_double_word(d("D11"), 3);
        sim.memory.set_double_word(d("D22"), 8);
        seed(&mut sim.memory);
        run(&mut sim, &p);
        assert_eq!(sim.memory.bit(d("Y0")), !inverted);
        assert_eq!(sim.memory.word(d("D300")), 9);
        assert_eq!(flags(&sim.memory), [true, false, true]);
    }
    assert_eq!(
        action("DBSET K8M128F7 K1X0E1").native_words().unwrap(),
        [
            0x3702, 0x80f4, 0xe890, 0x0080, 0x0080, 0x00e4, 0x2482, 0x0080, 0x0080
        ]
    );
}

#[test]
fn matrices_reject_p_forms_and_keep_first_and_number_roles_separate() {
    for (name, _, wide) in ACTIONS {
        for first in [
            "K1Y20E0", "K1M80F7", "K1S80E1", "T255E0", "C199F0", "D9999E0",
        ] {
            assert!(IndexedBitNumberAction::parse(name, &args(&format!("{first} K0"))).is_ok());
        }
        for first in ["K1X0E0", "X0E0", "M0E0", "E1", "F1", "K0", "H1"] {
            assert!(
                IndexedBitNumberAction::parse(name, &args(&format!("{first} K0"))).is_err(),
                "{name} {first}"
            );
        }
        for number in [
            "K0", "H000F", "K1X0E0", "K1Y0F7", "K1M80E1", "K1S80F1", "T255E0", "C199F0", "D9999E0",
            "E1", "F7",
        ] {
            assert!(
                IndexedBitNumberAction::parse(name, &args(&format!("D20E0 {number}"))).is_ok(),
                "{name} {number}"
            );
        }
        for number in ["K-1", "HFFFF", "K32", "X0E0", "E1F0", "F8", "K1X0E8"] {
            assert!(
                IndexedBitNumberAction::parse(name, &args(&format!("D20E0 {number}"))).is_err()
            );
        }
        assert_eq!(
            IndexedBitNumberAction::parse(name, &args("D20E0 K16")).is_ok(),
            wide
        );
        assert_eq!(
            IndexedBitNumberAction::parse(name, &args("C200E0 K0")).is_ok(),
            wide
        );
        assert!(!IndexedBitNumberAction::supports(&format!("{name}P")));
        assert!(IndexedBitNumberAction::parse(&format!("{name}P"), &args("D20E0 K0")).is_err());
    }
    for (name, _, _, wide, _) in CONTACTS {
        for first in ["K1X0E0", "K0", "H1", "E1", "F1", "M0E0"] {
            assert!(IndexedBitNumberPredicate::parse(name, &args(&format!("{first} K0"))).is_err());
        }
        for raw in ["D20E0 F7", "K1M80E0 K1X0F7", "T255E0 E1"] {
            assert!(IndexedBitNumberPredicate::parse(name, &args(raw)).is_ok());
        }
        assert_eq!(
            IndexedBitNumberPredicate::parse(name, &args("C200E0 K0")).is_ok(),
            wide
        );
        assert_eq!(
            IndexedBitNumberPredicate::parse(name, &args("D20E0 K16")).is_ok(),
            wide
        );
        assert!(IndexedBitNumberPredicate::parse(name, &args("D20E0 K-1")).is_err());
        assert!(!IndexedBitNumberPredicate::supports(&format!("{name}P")));
    }
    assert!(!IndexedBitNumberAction::supports("OUT"));
    assert!(!IndexedBitNumberPredicate::supports("LD"));
    assert!(!IndexedBitNumberPredicate::supports("LD&"));
    assert!(!IndexedBitNumberAction::has_modifiers(&args("D20 H000F")));
}

#[test]
fn sixteen_suffix_banks_remain_signed_word_offsets_in_both_read_roles() {
    for (suffix, alias) in [
        ("E0", "D1028"),
        ("F0", "D1029"),
        ("E1", "D1182"),
        ("F1", "D1183"),
        ("E2", "D1184"),
        ("F2", "D1185"),
        ("E3", "D1186"),
        ("F3", "D1187"),
        ("E4", "D1188"),
        ("F4", "D1189"),
        ("E5", "D1190"),
        ("F5", "D1191"),
        ("E6", "D1192"),
        ("F6", "D1193"),
        ("E7", "D1194"),
        ("F7", "D1195"),
    ] {
        for name in ["BSET", "DBSET"] {
            let mut m = Memory::default();
            m.set_word(d(alias), -2);
            let neighbor = Device {
                index: d(alias).index + 1,
                ..d(alias)
            };
            m.set_word(neighbor, i16::MIN);
            m.set_double_word(d("D8"), 3);
            let a = action(&format!("{name} D20{suffix} D10{suffix}"));
            let mut observed = BTreeSet::new();
            a.execute(&mut m, true, &mut observed);
            assert_eq!(m.double_word(d("D18")), 8);
            assert_eq!(a.modifier_devices(), vec![d(alias)]);
            assert!(!observed.contains(&neighbor));
            assert!(observed.contains(&d("D18")) && observed.contains(&d("D8")));
            assert_eq!(observed.contains(&d("D19")), name == "DBSET");
            assert_eq!(observed.contains(&d("D9")), name == "DBSET");
            let contact = pred(&format!(
                "{} D20{suffix} D10{suffix}",
                if name == "DBSET" { "DBLD" } else { "BLD" }
            ));
            assert!(contact.evaluate(&m).unwrap());
        }
    }
}

#[test]
fn packed_widths_use_scalar_rmw_and_never_physical_base_plus_number() {
    for wide in [false, true] {
        let prefix = if wide { "D" } else { "" };
        let limit = if wide { 8 } else { 4 };
        for digits in 1..=limit {
            for base in ["Y200", "M128", "S128"] {
                let original = d(base);
                let effective = Device {
                    index: original.index + 1,
                    ..original
                };
                let width = digits * 4;
                let end = Device {
                    index: effective.index + width,
                    ..effective
                };
                let mut m = Memory::default();
                m.set_word(d("D1028"), 1);
                m.set_internal(original, true);
                m.set_internal(end, true);
                action(&format!("{prefix}BSET K{digits}{base}E0 K{}", width - 1)).execute(
                    &mut m,
                    true,
                    &mut BTreeSet::new(),
                );
                assert_eq!(packed(&m, effective, width), 1u32 << (width - 1));
                assert!(
                    pred(&format!("{prefix}BLD K{digits}{base}E0 K{}", width - 1))
                        .evaluate(&m)
                        .unwrap()
                );
                assert!(
                    !pred(&format!("{prefix}BLDI K{digits}{base}E0 K{}", width - 1))
                        .evaluate(&m)
                        .unwrap()
                );
                action(&format!("{prefix}BRST K{digits}{base}E0 K{}", width - 1)).execute(
                    &mut m,
                    true,
                    &mut BTreeSet::new(),
                );
                assert_eq!(packed(&m, effective, width), 0);
                assert!(m.bit(original) && m.bit(end));
            }
        }
        let last = if wide { 31 } else { 15 };
        for (op, power) in [
            ("BSET", true),
            ("BRST", true),
            ("BOUT", true),
            ("BOUT", false),
        ] {
            let mut m = Memory::default();
            put_group(&mut m, d("M128"), 4, 5);
            let guard = Device {
                index: 128 + last,
                ..d("M128")
            };
            m.set_internal(guard, true);
            action(&format!("{prefix}{op} K1M128E0 K{last}")).execute(
                &mut m,
                power,
                &mut BTreeSet::new(),
            );
            assert_eq!(packed(&m, d("M128"), 4), 5);
            assert!(m.bit(guard));
            assert!(
                !pred(&format!("{prefix}BLD K1M128E0 K{last}"))
                    .evaluate(&m)
                    .unwrap()
            );
            assert!(
                pred(&format!("{prefix}BLDI K1M128E0 K{last}"))
                    .evaluate(&m)
                    .unwrap()
            );
        }
    }
}

#[test]
fn dynamic_numbers_wrap_low_bits_and_input_groups_are_legal_only_as_number() {
    for (wide, raw, expected_bit) in [
        (false, -1, 15),
        (false, 16, 0),
        (false, 31, 15),
        (false, 32, 0),
        (false, -32768, 0),
        (true, -1, 31),
        (true, 16, 16),
        (true, 31, 31),
        (true, 32, 0),
        (true, i32::MIN, 0),
        (true, 65567, 31),
    ] {
        let prefix = if wide { "D" } else { "" };
        let mut m = Memory::default();
        m.set_word(d("D1028"), 1);
        m.set_double_word(d("D11"), raw);
        seed(&mut m);
        action(&format!("{prefix}BSET D20F0 D10E0")).execute(&mut m, true, &mut BTreeSet::new());
        assert_eq!(m.double_word(d("D20")) as u32, 1u32 << expected_bit);
        assert!(
            pred(&format!("{prefix}BLD D20F0 D10E0"))
                .evaluate(&m)
                .unwrap()
        );
        assert_eq!(flags(&m), [true, false, true]);
        assert!(!m.system_bit(1067));
    }
    for base in ["X20", "Y20", "M80", "S80"] {
        let mut m = Memory::default();
        m.set_word(d("D1028"), 1);
        put_group(
            &mut m,
            Device {
                index: d(base).index + 1,
                ..d(base)
            },
            4,
            15,
        );
        action(&format!("DBSET D20F0 K1{base}E0")).execute(&mut m, true, &mut BTreeSet::new());
        assert_eq!(m.double_word(d("D20")), 32768);
        assert!(
            pred(&format!("DBLD D20F0 K1{base}E0"))
                .evaluate(&m)
                .unwrap()
        );
    }
}

#[test]
fn direct_wide_f_number_keeps_adjacent_storage_and_original_descriptor() {
    // Existing OpenDVP/native-qualified exception. Vendor final validators
    // reject this direct wide-F form even though their emitter can encode it.
    for (bank, alias, descriptor) in [
        (0, 1029, [0x3a86, 0x0080]),
        (1, 1183, [0x6e86, 0x0180]),
        (2, 1185, [0x7286, 0x0180]),
        (3, 1187, [0x7686, 0x0180]),
        (4, 1189, [0x7a86, 0x0180]),
        (5, 1191, [0x7e86, 0x0180]),
        (6, 1193, [0x8286, 0x0180]),
        (7, 1195, [0x8686, 0x0180]),
    ] {
        let mut m = Memory::default();
        let low = d(&format!("D{alias}"));
        let high = d(&format!("D{}", alias + 1));
        m.set_word(low, 31);
        m.set_word(high, -1);
        let a = action(&format!("DBSET D20E0 F{bank}"));
        let words = a.native_words().unwrap();
        assert_eq!(&words[5..9], [descriptor[0], descriptor[1], 0x0080, 0x0080]);
        let mut observed = BTreeSet::new();
        a.execute(&mut m, true, &mut observed);
        assert_eq!(m.double_word(d("D20")), i32::MIN);
        assert!(observed.contains(&low) && observed.contains(&high));
        let source = a.resolved_source(1, &m).unwrap();
        assert_eq!(source.read(&m), -65505);
        assert!(pred(&format!("DBLD D20E0 F{bank}")).evaluate(&m).unwrap());
        assert!(
            IndexedBitNumberPredicate::parse("DBLD", &args(&format!("F{bank} D20E0"))).is_err()
        );
    }
}

#[test]
fn first_then_number_then_writable_target_failures_have_ordered_observation() {
    for first_fails in [true, false] {
        let mut m = Memory::default();
        m.set_word(d(if first_fails { "D1028" } else { "D1195" }), -30000);
        let mut observed = BTreeSet::new();
        action("DBSET D20E0 D10F7").execute(&mut m, true, &mut observed);
        assert!(observed.contains(&d("D1028")));
        assert_eq!(observed.contains(&d("D1195")), !first_fails);
        assert_eq!(observed.contains(&d("D20")), !first_fails);
        assert!(!m.execution_limitations.is_empty());
        assert!(!m.system_bit(1067));
        let mut observed = BTreeSet::new();
        assert!(pred("DBLDI D20E0 D10F7").visit(&m, &mut observed).is_err());
        assert_eq!(observed.contains(&d("D1195")), !first_fails);
    }
    // First role reads readonly system bits successfully; write qualification
    // is deliberately late, after the n snapshot. Contacts need only read.
    let mut m = Memory::default();
    m.set_word(d("D1028"), 1);
    m.set_system(1000, true);
    m.set_word(d("D10"), 0);
    let mut observed = BTreeSet::new();
    action("BSET K1M999E0 D10F0").execute(&mut m, true, &mut observed);
    assert!(observed.contains(&d("M1000")) && observed.contains(&d("D10")));
    assert!(m.system_bit(1000));
    assert!(!m.execution_limitations.is_empty());
    assert!(pred("BLD K1M999E0 D10F0").evaluate(&m).unwrap());
}

#[test]
fn target_number_aliases_and_own_index_pair_store_keep_both_snapshots() {
    let mut m = Memory::default();
    m.set_word(d("D1028"), 1);
    action("BSET D1027E0 D1027E0").execute(&mut m, true, &mut BTreeSet::new());
    assert_eq!(m.word(d("D1028")), 3); // old1, n1 => set bit1.
    let mut m = Memory::default();
    m.set_word(d("D1027"), 88);
    m.set_word(d("D1028"), 1);
    m.set_word(d("D1029"), 0x1234);
    m.set_word(d("D1030"), 99);
    action("DBRST D1027E0 K0").execute(&mut m, true, &mut BTreeSet::new());
    assert_eq!(
        [
            m.word(d("D1027")),
            m.word(d("D1028")),
            m.word(d("D1029")),
            m.word(d("D1030"))
        ],
        [88, 0, 0x1234, 99]
    );
    let mut m = Memory::default();
    put_group(&mut m, d("M80"), 16, 2);
    action("BSET K4M80E0 K1M80F0").execute(&mut m, true, &mut BTreeSet::new());
    assert_eq!(packed(&m, d("M80"), 16), 6);
}

#[test]
fn bout_false_visits_but_set_reset_false_skip_all_sources() {
    for (name, _, _) in ACTIONS {
        let mut m = Memory::default();
        m.set_double_word(d("D20"), 15);
        m.set_double_word(d("D10"), 2);
        let a = action(&format!("{name} D20E0 D10F0"));
        let mut observed = BTreeSet::new();
        seed(&mut m);
        a.execute(&mut m, false, &mut observed);
        assert_eq!(m.double_word(d("D20")), if a.is_out() { 11 } else { 15 });
        assert_eq!(observed.is_empty(), !a.is_out());
        assert_eq!(a.should_resolve(false), a.is_out());
        assert_eq!(flags(&m), [true, false, true]);
        m.set_word(d("D1028"), -30000);
        observed.clear();
        a.execute(&mut m, false, &mut observed);
        assert_eq!(m.execution_limitations.is_empty(), !a.is_out());
        assert_eq!(observed.is_empty(), !a.is_out());
    }
}

#[test]
fn contacts_short_circuit_both_operands_and_nc_or_inv_cannot_hide_faults() {
    for (name, prefix, _, _, _) in CONTACTS {
        let incoming = match prefix {
            "LD" => "",
            "AND" => "LD X0\n",
            "OR" => "LDI X0\n",
            _ => unreachable!(),
        };
        let p = compile_il(&format!("{incoming}{name} D20E0 D10F7\nOUT Y0\nEND")).unwrap();
        let mut sim = Simulator::default();
        sim.memory.set_word(d("D1028"), -30000);
        sim.memory.set_word(d("D1195"), -30000);
        if prefix == "LD" {
            sim.scan(&p, 0);
            assert_ne!(sim.last_scan, ScanStatus::Complete);
            assert!(!sim.memory.bit(d("Y0")));
        } else {
            run(&mut sim, &p);
            assert_eq!(sim.memory.bit(d("Y0")), prefix == "OR");
            assert!(!sim.observed_devices.contains(&d("D1028")));
            assert!(!sim.observed_devices.contains(&d("D1195")));
        }
        assert!(
            pred(&format!("{name} D20E0 D10F7"))
                .evaluate(&sim.memory)
                .is_err()
        );
    }
    for name in ["BLDI", "DBLDI"] {
        let p = compile_il(&format!("{name} D20E0 K0\nINV\nOUT Y0\nEND")).unwrap();
        let mut sim = Simulator::default();
        sim.memory.set_word(d("D1028"), -30000);
        assert!(!p.networks[0].condition.evaluate(&sim.memory));
        sim.scan(&p, 0);
        assert_ne!(sim.last_scan, ScanStatus::Complete);
        assert!(!sim.memory.bit(d("Y0")));
        assert!(!sim.memory.system_bit(1067));
    }
}

#[test]
fn mc_false_bout_clears_but_numeric_read_contacts_ignore_master_context() {
    for name in ["BOUT", "DBOUT", "BSET", "DBSET", "BRST", "DBRST"] {
        let p = compile_il(&format!(
            "LD X0\nMC N0\nLDI X7\n{name} D20E0 K2\nMCR N0\nEND"
        ))
        .unwrap();
        let mut sim = Simulator::default();
        sim.memory.set_double_word(d("D20"), 15);
        run(&mut sim, &p);
        assert_eq!(
            sim.memory.double_word(d("D20")),
            if name.contains("OUT") { 11 } else { 15 }
        );
        assert_eq!(
            sim.observed_devices.contains(&d("D20")),
            name.contains("OUT")
        );
    }
    let p = compile_il("LD X0\nMC N0\nDBLD D20E0 D10F0\nOUT Y0\nMCR N0\nEND").unwrap();
    let mut sim = Simulator::default();
    sim.memory.set_double_word(d("D20"), 1);
    run(&mut sim, &p);
    for raw in ["D20", "D21", "D10", "D11"] {
        assert!(sim.observed_devices.contains(&d(raw)));
    }
    assert!(!sim.memory.bit(d("Y0")));
    // An actual inactive STL clears master as well as output context, so LDI
    // alone cannot power the numeric writer even though it is still visited.
    let p = compile_il("STL S0\nLDI X7\nBOUT D20E0 K2\nRET\nEND").unwrap();
    let mut sim = Simulator::default();
    assert!(!sim.memory.bit(d("S0")));
    run(&mut sim, &p);
    assert_eq!(sim.memory.word(d("D20")), 0);
    assert!(sim.observed_devices.contains(&d("D20")));
    // Isolate output context in the resumable VM without inventing a source
    // program: MC/MCR inside STL is forbidden by the compiler. This synthetic
    // control state tests dispatch only; it is not a native source fixture.
    let p = compile_il("LDI X7\nBOUT D20E0 K2\nEND").unwrap();
    let mut sim = Simulator::default();
    sim.begin_plan_scan(&p, 0, true).unwrap();
    sim.execute_plan_step(&p).unwrap();
    assert!(sim.control.effective_power());
    sim.control.out_enabled = false;
    sim.execute_plan_step(&p).unwrap();
    assert_eq!(sim.memory.word(d("D20")), 4);
    sim.execute_plan_step(&p).unwrap();
    assert_eq!(sim.last_scan, ScanStatus::Complete);
}

#[test]
fn nested_blocks_stack_and_loops_preserve_logic_and_live_address_visits() {
    let p = compile_il("BLD D0E0 K0\nLD X0\nDBLD C200F0 K31\nORB\nANB\nMPS\nBANI D0E0 K1\nOUT Y0\nMPP\nBOR D0E0 K1\nOUT Y1\nEND").unwrap();
    let mut sim = Simulator::default();
    for value in [0, 1, 2, 3] {
        for input in [false, true] {
            for counter in [0, i32::MIN] {
                sim.memory.set_word(d("D0"), value);
                sim.memory.set_input(d("X0"), input);
                sim.memory.set_double_word(d("C200"), counter);
                run(&mut sim, &p);
                let condition = value & 1 != 0 && (input || counter < 0);
                assert_eq!(sim.memory.bit(d("Y0")), condition && value & 2 == 0);
                assert_eq!(sim.memory.bit(d("Y1")), condition || value & 2 != 0);
            }
        }
    }
    let p =
        compile_il("LD X0\nMOV K0 E0\nFOR K3\nDBSET D20E0 E0\nADD E0 K2 E0\nNEXT\nEND").unwrap();
    let mut sim = Simulator::default();
    sim.memory.set_input(d("X0"), true);
    run(&mut sim, &p);
    assert_eq!(
        ["D20", "D22", "D24"].map(|raw| sim.memory.double_word(d(raw))),
        [1, 4, 16]
    );
    assert!(sim.observed_devices.contains(&d("D25")));
}

#[test]
fn counter_transitions_and_natural_storage_do_not_touch_adjacent_counters() {
    for (base, offset, effective) in [
        ("C198", 0, 198),
        ("C199", 0, 199),
        ("C199", 1, 200),
        ("C200", -1, 199),
        ("C200", 0, 200),
        ("C254", 1, 255),
    ] {
        let mut m = Memory::default();
        m.set_word(d("D1028"), offset);
        m.set_double_word(d("C200"), 123456);
        m.set_double_word(d("C201"), 654321);
        let target = d(&format!("C{effective}"));
        m.set_double_word(target, 0);
        let mut observed = BTreeSet::new();
        action(&format!("DBSET {base}E0 K31")).execute(&mut m, true, &mut observed);
        assert_eq!(
            m.double_word(target),
            if effective == 199 { 0 } else { i32::MIN }
        );
        assert_eq!(
            pred(&format!("DBLD {base}E0 K31")).evaluate(&m).unwrap(),
            effective != 199
        );
        if effective == 199 {
            assert_eq!(m.double_word(d("C200")), 123456);
            assert!(!observed.contains(&d("C200")));
        }
        if effective == 200 {
            assert_eq!(m.double_word(d("C201")), 654321);
        }
    }
    let mut m = Memory::default();
    m.set_word(d("D1028"), -1);
    m.set_double_word(d("T254"), 0);
    action("DBSET T255E0 K31").execute(&mut m, true, &mut BTreeSet::new());
    assert_eq!(m.double_word(d("T254")), i32::MIN);
    m.set_word(d("D1028"), 0);
    assert!(pred("DBLD T255E0 K0").evaluate(&m).is_err());
    assert!(
        action("DBSET T255E0 K0")
            .prepare(&m, &mut BTreeSet::new())
            .is_err()
    );
    assert!(
        action("BSET T255E0 K0")
            .prepare(&m, &mut BTreeSet::new())
            .is_ok()
    );
}

#[test]
fn complete_model_spans_and_low_m_exclusions_hold_in_both_operand_roles() {
    for last in [4999, 9999] {
        let mut m = Memory::default();
        m.data_register_limit = Some(last);
        m.set_word(d("D1028"), -1);
        for raw in [format!("D{last}E0 K0"), format!("D20F0 D{last}E0")] {
            assert!(
                IndexedBitNumberAction::parse("DBSET", &args(&raw))
                    .unwrap()
                    .prepare(&m, &mut BTreeSet::new())
                    .is_ok()
            );
            assert!(
                IndexedBitNumberPredicate::parse("DBLD", &args(&raw))
                    .unwrap()
                    .evaluate(&m)
                    .is_ok()
            );
        }
        m.set_word(d("D1028"), 0);
        for raw in [format!("D{last}E0 K0"), format!("D20F0 D{last}E0")] {
            assert!(
                IndexedBitNumberAction::parse("DBSET", &args(&raw))
                    .unwrap()
                    .prepare(&m, &mut BTreeSet::new())
                    .is_err()
            );
            assert!(
                IndexedBitNumberPredicate::parse("DBLDI", &args(&raw))
                    .unwrap()
                    .evaluate(&m)
                    .is_err()
            );
            assert!(
                IndexedBitNumberAction::parse("BSET", &args(&raw))
                    .unwrap()
                    .prepare(&m, &mut BTreeSet::new())
                    .is_ok()
            );
        }
    }
    for raw in [
        "K1M1284E0 K0",
        "K2M1532E0 K0",
        "D20E0 K1M1284F0",
        "K2S1020E0 K0",
        "K1Y377E0 K0",
    ] {
        let m = Memory::default();
        assert!(
            IndexedBitNumberAction::parse("DBSET", &args(raw))
                .unwrap()
                .prepare(&m, &mut BTreeSet::new())
                .is_err(),
            "{raw}"
        );
        assert!(
            IndexedBitNumberPredicate::parse("DBLDI", &args(raw))
                .unwrap()
                .evaluate(&m)
                .is_err()
        );
    }
    let mut m = Memory::default();
    m.relay_limit = Some(511);
    assert!(
        action("DBSET K1M508E0 K0")
            .prepare(&m, &mut BTreeSet::new())
            .is_ok()
    );
    assert!(
        action("DBSET K1M509E0 K0")
            .prepare(&m, &mut BTreeSet::new())
            .is_err()
    );
}

#[test]
fn pure_prepare_and_monitoring_track_effective_spans_not_label_bases() {
    let mut m = Memory::default();
    m.set_word(d("D1028"), 1);
    m.set_word(d("D1029"), 2);
    m.set_double_word(d("D21"), 5);
    m.set_double_word(d("D12"), 1);
    let a = action("DBSET D20E0 D10F0");
    let mut observed = BTreeSet::new();
    a.prepare(&m, &mut observed).unwrap();
    assert_eq!(m.double_word(d("D21")), 5);
    assert_eq!(
        observed,
        BTreeSet::from([
            d("D1028"),
            d("D1029"),
            d("D21"),
            d("D22"),
            d("D12"),
            d("D13")
        ])
    );
    assert_eq!(a.dest(), d("D20"));
    assert_eq!(a.display_value(&m), "5");
    assert!(a.resolved_source(2, &m).is_err());
    let p = pred("DBLD D20E0 D10F0");
    assert_eq!(p.source_count(), 2);
    assert!(p.short_circuits());
    assert!(!p.evaluate(&m).unwrap());
    assert_eq!(p.display_value(&m), "0");
    m.set_word(d("D1029"), -30000);
    observed.clear();
    a.execute(&mut m, true, &mut observed);
    assert!(!m.execution_limitations.is_empty());
    assert_eq!(m.double_word(d("D21")), 5);
    let mut ui = BTreeSet::new();
    a.observed_devices(&m, &mut ui);
    assert!(ui.contains(&d("D21")) && ui.contains(&d("D22")));
    assert!(!ui.contains(&d("D20")));
}

#[test]
fn explicit_flag_targets_change_only_selected_bits_and_ordinary_paths_agree() {
    for (name, _, wide) in ACTIONS {
        for power in [false, true] {
            let mut ordinary = Memory::default();
            ordinary.set_double_word(d("D20"), 0x12345678);
            ordinary.set_double_word(d("D10"), -1);
            seed(&mut ordinary);
            let mut indexed = ordinary.clone();
            BitAction::parse(name, &args("D20 D10"))
                .unwrap()
                .execute(&mut ordinary, power);
            action(&format!("{name} D20E0 D10F0")).execute(
                &mut indexed,
                power,
                &mut BTreeSet::new(),
            );
            let expected = if !power && !name.contains("OUT") {
                0x12345678u32
            } else if name.contains("RST") || !power {
                if wide {
                    0x12345678
                } else {
                    0x12345678 & !0x8000
                }
            } else if wide {
                0x92345678
            } else {
                0x1234d678
            };
            assert_eq!(indexed.double_word(d("D20")) as u32, expected);
            assert_eq!(
                indexed.double_word(d("D20")),
                ordinary.double_word(d("D20"))
            );
            assert_eq!(flags(&indexed), [true, false, true]);
            let suffix = if wide { "D" } else { "" };
            assert_eq!(
                pred(&format!("{suffix}BLD D20E0 D10F0"))
                    .evaluate(&indexed)
                    .unwrap(),
                NumericPredicate::parse(&format!("{suffix}BLD"), &args("D20 D10"))
                    .unwrap()
                    .evaluate(&ordinary)
            );
        }
    }
    let mut m = Memory::default();
    put_group(&mut m, d("M1019"), 4, 15);
    action("BRST K1M1019E0 K2").execute(&mut m, true, &mut BTreeSet::new());
    assert_eq!(flags(&m), [true, false, true]);
    action("BOUT K1M1019E0 K1").execute(&mut m, false, &mut BTreeSet::new());
    assert_eq!(flags(&m), [false, false, true]);
    action("DBSET K1M1019E0 K2").execute(&mut m, true, &mut BTreeSet::new());
    assert_eq!(flags(&m), [false, true, true]);
}

#[test]
fn dynamic_clock_sources_require_known_levels_before_nc_or_rmw_reads() {
    use crate::system_relays::{ClockProfile, ClockState};
    let mut m = Memory::default();
    m.system_relays.set_profile(ClockProfile::InstalledFixed);
    m.set_word(d("D1182"), 0);
    let mut observed = BTreeSet::new();
    assert!(pred("BLDI K1M1011E1 K0").visit(&m, &mut observed).is_err());
    assert!(observed.contains(&d("M1011")));
    for first in ["K1M1011E0", "K1M1011E1"] {
        assert!(pred(&format!("DBLDI {first} K0")).evaluate(&m).is_err());
    }
    let p = compile_il("BLDI K1M1011E1 K0\nINV\nOUT Y0\nEND").unwrap();
    assert!(!p.networks[0].condition.evaluate(&m));
    let a = action("BOUT D20E0 K1M1011E1");
    m.set_word(d("D20"), 0x1234);
    observed.clear();
    a.execute(&mut m, true, &mut observed);
    assert_eq!(m.word(d("D20")), 0x1234);
    assert!(!m.execution_limitations.is_empty());
    assert!(observed.contains(&d("D20")) && observed.contains(&d("M1011")));
    m.execution_limitations.clear();
    observed.clear();
    action("BSET D20E0 K1M1011E1").execute(&mut m, false, &mut observed);
    assert!(observed.is_empty() && m.execution_limitations.is_empty());
    let p = compile_il("LD X0\nBANI K1M1011E1 K0\nOUT Y0\nEND").unwrap();
    assert!(!p.networks[0].condition.evaluate(&m));
    assert!(pred("BLDI K1M80E1 K0").evaluate(&m).is_ok());
    ClockState::seed_installed_levels(&mut m, [true, false, true, false]).unwrap();
    assert!(pred("BLD K1M1011E1 K0").evaluate(&m).unwrap());
    assert!(!pred("BLDI K1M1011E1 K0").evaluate(&m).unwrap());
    m.set_word(d("D20"), 0);
    action("BOUT D20E0 K1M1011E1").execute(&mut m, true, &mut BTreeSet::new());
    assert_eq!(m.word(d("D20")), 1 << 5);
    let m = Memory::default();
    assert!(pred("BLDI K1M1011E0 K0").evaluate(&m).is_ok());
}

#[test]
fn public_program_api_cannot_invent_pulse_headers_for_numeric_bit_forms() {
    for (name, _, _) in ACTIONS {
        assert!(compile_il(&format!("LD X0\n{name}P D20E0 K0\nEND")).is_err());
        let mut p = compile_il(&format!("LD X0\n{name} D20E0 K0\nEND")).unwrap();
        let original = p.networks[0].actions[0].clone();
        p.networks[0].actions[0] = crate::plc::Action::Pulse(Box::new(original));
        assert!(
            crate::es2_encoder::encode(&p).is_err(),
            "{name} must have no native P header"
        );
    }
    for (name, prefix, _, _, _) in CONTACTS {
        let lead = if prefix == "LD" { "" } else { "LD X0\n" };
        assert!(compile_il(&format!("{lead}{name}P D20E0 K0\nOUT Y0\nEND")).is_err());
    }
}
